<script setup lang="ts">
import { ref, onBeforeUnmount } from 'vue';
import { ScanFace, ArrowLeft, ShieldCheck, Clock3, CheckCircle2, LockKeyhole, Unplug } from 'lucide-vue-next';
import { api, send, labels, time } from '../api';
import Camera from '../components/Camera.vue';
const camera = ref<InstanceType<typeof Camera>>(), token = ref(sessionStorage.getItem('erams_kiosk') ?? ''), paired = ref(!!token.value), kind = ref('AM_IN'), busy = ref(false), error = ref(''), success = ref<any>(null), now = ref(new Date());
const tick = setInterval(() => now.value = new Date(), 1000); let clear: ReturnType<typeof setTimeout> | undefined;
onBeforeUnmount(() => { clearInterval(tick); clearTimeout(clear); });
function pair() { token.value = token.value.trim(); if (!token.value) return; sessionStorage.setItem('erams_kiosk', token.value); paired.value = true; }
function unpair() { camera.value?.stop(); sessionStorage.removeItem('erams_kiosk'); token.value = ''; paired.value = false; success.value = null; error.value = ''; }
async function punch() { busy.value = true; error.value = ''; success.value = null; try { const image = camera.value!.capture(); success.value = await api('/kiosk/punch', { ...send('POST', { image, kind: kind.value, key: crypto.randomUUID() }), headers: { Authorization: `Kiosk ${token.value}` } }); clearTimeout(clear); clear = setTimeout(() => success.value = null, 8000); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
</script>
<template><main class="kiosk-shell"><header class="kiosk-header"><RouterLink to="/" class="brand"><div class="brand-mark"><ScanFace :size="27" /></div><div><strong>e-RAMS<span>2.0</span></strong><small>SAN JUAN · SOUTHERN LEYTE</small></div></RouterLink><RouterLink to="/" class="text-button"><ArrowLeft :size="16" /> Workspace</RouterLink></header><div class="kiosk-content"><div class="kiosk-intro"><p class="eyebrow">MUNICIPAL ATTENDANCE KIOSK</p><h1>Ready for your workday.</h1><p>Choose your attendance event and look at the camera.</p><div class="kiosk-clock">{{ new Intl.DateTimeFormat('en-PH', { timeZone: 'Asia/Manila', hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(now) }}</div><span class="muted">{{ new Intl.DateTimeFormat('en-PH', { timeZone: 'Asia/Manila', dateStyle: 'full' }).format(now) }} · PHT</span></div><section v-if="!paired" class="panel kiosk-pair"><LockKeyhole :size="30" /><h2>Pair this kiosk</h2><p>Ask your administrator for a device token. The token stays in this browser tab for this session.</p><form @submit.prevent="pair"><label>Device token<input v-model="token" type="password" required autocomplete="off" spellcheck="false" /></label><button class="button primary full">Connect kiosk</button></form></section><section v-else class="panel kiosk-capture"><div class="kiosk-events" role="group" aria-label="Attendance event"><button v-for="(label, value) in labels" :key="value" :class="['event-button', { selected: kind === value }]" :disabled="busy" @click="kind = value; success = null"><Clock3 :size="17" />{{ label }}</button></div><Camera ref="camera" /><div v-if="success" class="kiosk-success" role="status"><CheckCircle2 :size="30" /><div><strong>Thank you, {{ success.name }}.</strong><p>{{ labels[success.kind] }} recorded at {{ time(success.occurredAt) }}.</p></div></div><p v-if="error" class="alert error" role="alert">{{ error }}</p><button class="button primary full capture-button" :disabled="busy" @click="punch"><ScanFace :size="22" />{{ busy ? 'Verifying your face…' : `Record ${labels[kind].toLowerCase()}` }}</button><div class="kiosk-capture-footer"><span><ShieldCheck :size="15" /> Camera images are not saved</span><button class="text-button" :disabled="busy" @click="unpair"><Unplug :size="14" /> Disconnect kiosk</button></div></section><p class="kiosk-help">Need another way to record attendance? Your HR officer can help with a manual entry.</p></div><footer class="kiosk-footer">Authorized employees only · Face processing requires prior enrollment and consent.</footer></main></template>
